/* 
  Using Custom Headers for Versioning 
*/

// Frontend Request
fetch('https://api.stripe.com/v1/charges', {
  headers: {
    'Authorization': 'Bearer sk_test_123',
    // Asking the server to use the legacy 2020 API behavior!
    'Stripe-Version': '2020-08-27'
  }
});

// Backend Logic
app.get('/charges', (req, res) => {
  const version = req.headers['stripe-version'];

  if (version === '2020-08-27') {
    return res.json(formatChargeLegacy());
  }
  return res.json(formatChargeModern());
});
